class ProprioceptionObs:
    """本体观测值类"""
    def __init__(self, num_joints=12):
        """
        Args:
            num_joints (int): 关节数目，默认12个
        """
        self.base_ang_vel = np.zeros(3, dtype=np.float32)
        self.projected_gravity = np.zeros(3, dtype=np.float32)
        self.joint_pos = np.zeros(num_joints, dtype=np.float32)
        self.joint_vel = np.zeros(num_joints, dtype=np.float32)
        self.base_quat = np.array([1.0, 0.0, 0.0, 0.0], dtype=np.float32) # dance 增加

class RunState(Enum):
    """运行状态枚举"""
    IDLE = 1       # 失能状态
    IDLE2 = 5      # 待机状态
    STANCE = 2     # 站立状态
    TROT = 3       # 小跑步态
    LIEDOWN = 4    # 躺下状态


class SpeedCmd():
    """速度命令类，包含yaw kp控制"""
    def __init__(self, yaw_kp: int | float):
        self.LB = 0
        self.RB = 0
        self.KEY_A = 0
        self.KEY_B = 0
        self.KEY_X = 0
        self.KEY_Y = 0

        self.x_vel_cmd = 0.0
        self.y_vel_cmd = 0.0
        self.yaw_vel_cmd = 0.0

        self.up_down = 0.0
        self.left_right = 0.0
        self.LT = 1.0
        self.RT = 1.0

        self.now_yaw = 0.0
        self.last_yaw = 0.0
        self.now_yaw_multi = 0.0  # 多圈计数的yaw角
        self.cycle_count = 0
        self.tar_yaw = 0.0
        self.yaw_kp = yaw_kp
    
    def get_multi_yaw(self, w, x, y, z):
        """根据四元数计算当前的多圈yaw角"""
        # 得到当前yaw角
        self.now_yaw = self._get_yaw_from_quat(w, x, y, z)
        if self.last_yaw < -3.0 and self.now_yaw > 3.0:
            self.cycle_count -= 1
        elif self.last_yaw > 3.0 and self.now_yaw < -3.0:
            self.cycle_count += 1
        # 计算多圈yaw角
        self.now_yaw_multi = self.now_yaw + self.cycle_count * 2.0 * np.pi
        # 记录上一次的yaw角
        self.last_yaw = self.now_yaw

    def yaw_kp_cal(self):
        """计算当前的yaw kp"""
        if self.yaw_kp == 0.0:
            return 0.0
        else:
            return self.yaw_kp * (self.tar_yaw - self.now_yaw_multi)
    
    def _get_yaw_from_quat(self, w, x, y, z):
        """根据四元数计算当前的yaw角"""
        return np.arctan2(2.0 * (w * z + x * y), 1.0 - 2.0 * (y * y + z * z))


class RunTimeRecord:
    """运行时间记录类"""
    def __init__(self, mean_count: int = 10, init_skip: int = 5):
        self.mean_count = mean_count
        self.init_skip = init_skip
        self.count = 0

        self.run_time_mean = 0
        self.run_time_max = 0
        self.run_time_min = 100000.0
        self.time_queue = deque(maxlen=mean_count)
    
    def record(self, run_time: float):
        if self.count < self.init_skip:
            self.count += 1
            return

        if run_time > self.run_time_max:
            self.run_time_max = run_time
        if run_time < self.run_time_min:
            self.run_time_min = run_time

        self.time_queue.append(run_time)
        self.run_time_mean = sum(self.time_queue) / len(self.time_queue)

    def get_time(self):
        """获取当前的运行时间统计信息

        Returns:
            tuple: (mean, max, min)
        """
        return self.run_time_mean, self.run_time_max, self.run_time_min


class BaseController(Node, ABC):
    """控制器基类

    Args:
        Node (_type_): ros2 Node基类
        ABC (_type_): 抽象类
    """
    def __init__(self, yaml_path, node_name):
        super().__init__(node_name)
        
        # 读取yaml文件
        with open(yaml_path, 'r') as f:
            try:
                param = yaml.safe_load(f)
                self.param = param["parameters"]
            except yaml.YAMLError as e:
                self.get_logger().error(f"YAML解析失败: {e}")
                return

        # 初始化观测数据
        self.propri_obs = ProprioceptionObs(self.param["policyJointNum"])
        
        # 初始化变量
        self.twist_cmd = Twist()
        self.speed_raw_cmd = SpeedCmd(self.param["yawKp"])
        self.run_state = RunState.IDLE
        self.run_time_record = RunTimeRecord(10, 20)
        self.log_decimation = int(self.param["RLFrequency"] / 5)
        self.log_count = 0
        self.commandFlag = False

        # self.last_cmd_x = 0.0
        # self.last_cmd_y = 0.0
        # self.rl_dt = 1.0 / self.param["RLFrequency"]
        # 减速斜坡限制 
        self.vel_smooth_xy = np.zeros(2, dtype=np.float32)  # 上一次平滑后的[x, y]速度
        self.vel_ramp_decel = np.array(self.param.get("vel_ramp_decel", [1.0, 1.0]), dtype=np.float32)
        self.rl_dt = 1.0 / self.param["RLFrequency"]


        # 按钮去抖动：记录上一次的按钮状态
        self.last_lb_state = False
        self.last_rb_state = False
        self.last_key_a_state = False
        self.last_key_b_state = False
        self.last_key_x_state = False
        self.last_key_y_state = False
        
        # 按钮冷却时间（防止连续触发）
        self.last_state_change_time = 0.0
        self.state_change_cooldown = 0.5  # 500ms 冷却时间

        # 外部状态机状态（参考joy_action_right_arm的cmd_callback模式）
        # 0: STATE_DISABLED, 1: STATE_DAMPING, 2: STATE_READY, 3: STATE_RUNNING
        self.external_system_state = LrsCmdStateFeedback.STATE_DISABLED  # 默认失能
        self.external_system_mode = LrsCmdStateFeedback.MODE_DEFAULT

        self.joy_timeout = 0.2  # 手柄超时时间（秒），0表示禁用
        self.joy_auto_zero = True  # 超时时自动清零命令
        self.last_joy_msg_time = 0.0
        self.joy_available = False
        self.get_logger().info(
            f"手柄超时检测: enabled={self.joy_timeout > 0}, "
            f"timeout={self.joy_timeout}s, "
            f"auto_zero={self.joy_auto_zero}"
        )


        # 创建 QoS 配置
        qos_profile = QoSProfile(
            depth=10,
            reliability=ReliabilityPolicy.RELIABLE,
            durability=DurabilityPolicy.TRANSIENT_LOCAL
        )

        # 传感器数据 QoS（高频数据，不需要重传）
        sensor_qos = QoSProfile(
            depth=10,
            history=HistoryPolicy.KEEP_LAST,
            reliability=ReliabilityPolicy.BEST_EFFORT,
            durability=DurabilityPolicy.VOLATILE
        )
        
        # ========== 订阅 ==========
        # 机器人状态（包含IMU和电机反馈）
        self.robot_state_sub = self.create_subscription(
            RobotState,
            self.param["lowStateTopic"],
            self.low_state_callback,
            sensor_qos
        )
        
        # 手柄指令
        self.joy_sub = self.create_subscription(
            Joy,
            self.param["joyTopic"],
            self.joy_callback,
            10
        )
        
        # 速度指令（导航等外部系统）
        self.twist_sub = self.create_subscription(
            Twist,
            "/rl_cmd_vel",  # 默认速度命令topic
            self.twist_callback,
            10
        )
        
        # 外部系统状态
        self.system_state_sub = self.create_subscription(
            LrsState,
            "/system/current_state",
            self.system_state_callback,
            10
        )
        
        # 外部状态机命令（参考joy_action_right_arm的cmd_callback模式）
        # 订阅状态切换命令，更新本地状态后发送反馈
        self.lrs_cmd_sub = self.create_subscription(
            LrsCmdState,
            "/system/lrs_cmd",
            self.cmd_callback,
            qos_profile
        )
        
        # ========== 发布 ==========
        motor_qos = QoSProfile(
            depth=10,
            history=HistoryPolicy.KEEP_LAST,
            reliability=ReliabilityPolicy.RELIABLE,
            durability=DurabilityPolicy.VOLATILE
            )
        # 电机命令
        self.motor_cmd_pub = self.create_publisher(
            MotorControl,
            self.param["jointCommandsTopic"],
            motor_qos
        )
        
        # 状态机命令
        self.lrs_cmd_pub = self.create_publisher(
            LrsCmdState,
            "/system/lrs_cmd",
            qos_profile
        )
        
        # 状态切换反馈（参考joy_action_right_arm）
        self.state_feedback_pub = self.create_publisher(
            LrsCmdStateFeedback,
            "/system/lrs_cmd_feedback",
            qos_profile
        )
        
        # 模式切换反馈（与状态切换反馈共用同一话题，LYOS状态机只监听 /system/lrs_cmd_feedback）
        self.mode_feedback_pub = self.create_publisher(
            LrsCmdStateFeedback,
            "/system/lrs_cmd_feedback",
            qos_profile
        )
        
        # 诊断信息
        self.diagnostic_pub = self.create_publisher(
            DiagnosticArray,
            "/diagnostics",
            10
        )
        
        # ========== 定时器 ==========
        self.controller_timer = self.create_timer(
            1.0 / self.param["RLFrequency"],
            self.run
        )

        # 如果flag是0，则默认运行TROT状态
        if self.param["FSMFlag"] == 0:
            self.run_state = RunState.TROT
        
        self.get_logger().info("Base Controller initialized")
 
        # 写入算法版本文件
        version_file = "/tmp/algo_version.yaml"
        try:
            with open(version_file, 'w') as f:
                f.write("algo_version: 1.1.0\n")
                f.write("dance_support: false\n")
                f.write("waist_support: true\n")
                f.write("walk_support: true\n")
                f.write("navigation_support: false\n")
                f.write("修改优先级为60，支持带腰行走。")
        except Exception as e:
            self.get_logger().warn(f"写入版本文件失败: {version_file}: {e}")



    def run(self):
        """按频率执行的推理函数"""
        # 开始运行计时
        start_time = time.perf_counter()
        
        # 处理手柄命令
        self.twist_cmd_process()
        
        # 进行网络推理
        self.inference()
        
        # 结束计时
        end_time = time.perf_counter()
        self.run_time_record.record((end_time - start_time) * 1e6)
        
        # 输出log信息
        self.show_log()

    def low_state_callback(self, msg: RobotState):
        """接收机器人状态信息（包含IMU和电机反馈）

        Args:
            msg (RobotState): 机器人状态信息
        """
        # IMU角速度  坐标系转换：参考(x前,y左) -> 您的(x左,y后) x = -y y = x
        self.propri_obs.base_ang_vel[0] = -msg.imu.angular_velocity.y
        self.propri_obs.base_ang_vel[1] = msg.imu.angular_velocity.x
        self.propri_obs.base_ang_vel[2] = msg.imu.angular_velocity.z

        # IMU四元数转重力向量
        # 坐标系转换：参考(x前,y左) -> 您的(x左,y后)
        # 转换关系：x_new = y_old, y_new = x_old
        ori = msg.imu.orientation
        gra_x_ref = 2.0 * (-ori.z * ori.x + ori.w * ori.y)
        gra_y_ref = -2.0 * (ori.z * ori.y + ori.w * ori.x)
        gra_z = 1.0 - 2.0 * (ori.w * ori.w + ori.z * ori.z)
        
        #  # IMU四元数 dance增加 默认imu正确
        # self.propri_obs.base_quat[0] = ori.w
        # self.propri_obs.base_quat[1] = ori.x
        # self.propri_obs.base_quat[2] = ori.y
        # self.propri_obs.base_quat[3] = ori.z

        #  # IMU四元数 dance增加
        c_pi4 = np.cos(np.pi / 4.0)  # ≈ 0.70710678
        self.propri_obs.base_quat[0] = c_pi4 * (ori.w + ori.z)
        self.propri_obs.base_quat[1] = c_pi4 * (ori.x - ori.y)
        self.propri_obs.base_quat[2] = c_pi4 * (ori.x + ori.y)
        self.propri_obs.base_quat[3] = c_pi4 * (ori.z - ori.w)

        # 转换到您的坐标系
        self.propri_obs.projected_gravity[0] = -gra_y_ref  # 您的x = 参考的y
        self.propri_obs.projected_gravity[1] = gra_x_ref  # 您的y = 参考的x（去掉负号）
        self.propri_obs.projected_gravity[2] = gra_z

        # 记录当前yaw角，用于yaw kp
        self.speed_raw_cmd.get_multi_yaw(ori.w, ori.x, ori.y, ori.z)

        # 关节位置与关节速度（只取Policy控制的关节）
        policy_indices = self.param.get("policy_joint_indices", list(range(self.param["policyJointNum"])))
        for i, idx in enumerate(policy_indices):
            if i < self.param["policyJointNum"] and idx < len(msg.motor_feedback.feedback):
                self.propri_obs.joint_pos[i] = msg.motor_feedback.feedback[idx].position - self.param["defaultPos"][idx]
                self.propri_obs.joint_vel[i] = msg.motor_feedback.feedback[idx].omega

    def joy_callback(self, msg: Joy):
        """接收手柄信息的回调函数

        Args:
            msg (Joy): 手柄信息
        """
        # 记录最后收到手柄消息的时间
        self.last_joy_msg_time = time.time()
        self.joy_available = True

        if self.param["JoyType"] == 0:  # Xinput
            self.speed_raw_cmd.LB = msg.buttons[4]
            self.speed_raw_cmd.RB = msg.buttons[5]
            # 修正：根据 joy_test_subscriber.cpp 测试结果
            # 实际按下 X/A/B/Y → 系统显示为 A/B/X/Y
            self.speed_raw_cmd.KEY_A = msg.buttons[1]  # A按钮实际对应索引1
            self.speed_raw_cmd.KEY_B = msg.buttons[2]  # B按钮实际对应索引2
            self.speed_raw_cmd.KEY_X = msg.buttons[0]  # X按钮实际对应索引0
            self.speed_raw_cmd.KEY_Y = msg.buttons[3]  # Y按钮对应索引3
            
            # 正确的轴映射：axes[1]控制x（前进），axes[0]控制y（左移）
            self.speed_raw_cmd.x_vel_cmd = msg.axes[1]       # 前进/后退 (左摇杆Y轴)
            self.speed_raw_cmd.y_vel_cmd = -msg.axes[0]      # 左移/右移 (左摇杆X轴，反转)
            self.speed_raw_cmd.yaw_vel_cmd = -msg.axes[2]    # 旋转 (右摇杆X轴，左右控制转向)

            self.speed_raw_cmd.left_right = -msg.axes[6]     # 十字键X轴 (需要反转)
            self.speed_raw_cmd.up_down = msg.axes[7]         # 十字键Y轴

            self.speed_raw_cmd.LT = msg.axes[3]             # 左扳机 (实际是轴3)
            self.speed_raw_cmd.RT = msg.axes[4]             # 右扳机 (实际是轴4)

        elif self.param["JoyType"] == 1:  # PS4/北通飞智
            self.speed_raw_cmd.LB = msg.buttons[6]
            self.speed_raw_cmd.RB = msg.buttons[7]
            self.speed_raw_cmd.x_vel_cmd = msg.axes[1]
            self.speed_raw_cmd.y_vel_cmd = msg.axes[0]
            self.speed_raw_cmd.yaw_vel_cmd = msg.axes[3]

        # 判断是否有命令值
        if (abs(self.speed_raw_cmd.x_vel_cmd) + 
            abs(self.speed_raw_cmd.y_vel_cmd) + 
            abs(self.speed_raw_cmd.yaw_vel_cmd)) < 0.05:
            self.commandFlag = False
        else:
            self.commandFlag = True

        # 按钮边缘检测（去抖动）：只在按钮按下的瞬间触发
        # 将按钮值转换为布尔值进行判断
        lb_current = bool(self.speed_raw_cmd.LB)
        rb_current = bool(self.speed_raw_cmd.RB)
        key_a_current = bool(self.speed_raw_cmd.KEY_A)
        key_b_current = bool(self.speed_raw_cmd.KEY_B)
        key_x_current = bool(self.speed_raw_cmd.KEY_X)
        key_y_current = bool(self.speed_raw_cmd.KEY_Y)
        
        lb_pressed = lb_current and not self.last_lb_state
        rb_pressed = rb_current and not self.last_rb_state
        key_a_pressed = key_a_current and not self.last_key_a_state
        key_b_pressed = key_b_current and not self.last_key_b_state
        key_x_pressed = key_x_current and not self.last_key_x_state
        key_y_pressed = key_y_current and not self.last_key_y_state

        # 调试日志：显示按钮状态
        # if lb_current or rb_current or key_a_current or key_b_current:
        #     self.get_logger().info(
        #         f"按钮状态: LB={lb_current}({lb_pressed}), RB={rb_current}({rb_pressed}), "
        #         f"A={key_a_current}({key_a_pressed}), B={key_b_current}({key_b_pressed})"
        #     )

        # 更新按钮状态
        self.last_lb_state = lb_current
        self.last_rb_state = rb_current
        self.last_key_a_state = key_a_current
        self.last_key_b_state = key_b_current
        self.last_key_x_state = key_x_current
        self.last_key_y_state = key_y_current

        # 注意：状态机切换已改为订阅外部 /system/lrs_cmd，不再由手柄LB+RB触发

    def cmd_callback(self, msg: LrsCmdState):
        """外部状态机命令回调（参考joy_action_right_arm的cmd_callback）
        
        收到状态/模式切换命令后：
        1. 先更新本地状态
        2. 再用本地变量发送反馈
        """
        if msg.cmd_type == LrsCmdState.CMD_TYPE_STATE_CHANGE:
            # 状态切换
            if msg.target_state <= 3:
                old_state = self.external_system_state
                self.external_system_state = msg.target_state
                self.get_logger().info(
                    f"外部状态切换: {old_state} -> {self.external_system_state}"
                )
                
                # 用本地变量发反馈
                feedback = LrsCmdStateFeedback()
                feedback.header.stamp = self.get_clock().now().to_msg()
                feedback.header.frame_id = self.get_name()
                feedback.current_state = self.external_system_state
                feedback.current_mode = self.external_system_mode
                self.state_feedback_pub.publish(feedback)
                
        elif msg.cmd_type == LrsCmdState.CMD_TYPE_MODE_CHANGE:
            # 模式切换
            if msg.target_mode <= 1:
                old_mode = self.external_system_mode
                self.external_system_mode = msg.target_mode
                self.get_logger().info(
                    f"外部模式切换: {old_mode} -> {self.external_system_mode}"
                )
                
                # 用本地变量发反馈
                feedback = LrsCmdStateFeedback()
                feedback.header.stamp = self.get_clock().now().to_msg()
                feedback.header.frame_id = self.get_name()
                feedback.current_state = self.external_system_state
                feedback.current_mode = self.external_system_mode
                self.mode_feedback_pub.publish(feedback)


    def twist_cmd_process(self):
        """对手柄、导航命令进行后处理"""

        # ========== 手柄超时检测 ==========
        if self.joy_timeout > 0:
            time_since_last_joy = time.time() - self.last_joy_msg_time
            if time_since_last_joy > self.joy_timeout:
                if self.joy_available:
                    self.get_logger().warn(
                        f"手柄连接超时！最后消息: {time_since_last_joy:.2f}秒前, "
                        f"清零手柄命令"
                    )
                    self.joy_available = False
                
                if self.joy_auto_zero:
                    # 清零手柄原始命令
                    self.speed_raw_cmd.x_vel_cmd = 0.0
                    self.speed_raw_cmd.y_vel_cmd = 0.0
                    self.speed_raw_cmd.yaw_vel_cmd = 0.0

        # 速度命令映射：手柄[-1,1]直接映射到实际速度范围
        # ===== 改动：先用临时变量，不直接赋值给twist_cmd =====
        target_x = self.speed_raw_cmd.x_vel_cmd * self.param["CommandLimit"][0]
        target_y = -self.speed_raw_cmd.y_vel_cmd * self.param["CommandLimit"][1]
        ang_vel_z = -self.speed_raw_cmd.yaw_vel_cmd * self.param["CommandLimit"][2]

        # 速度命令加上偏置
        target_x = target_x + self.param["CommandOffset"][0]
        target_y = target_y + self.param["CommandOffset"][1]
        ang_vel_z = ang_vel_z + self.param["CommandOffset"][2]
        
        # ===== 新增：减速斜坡限制（仅x/y，yaw不限） =====
        target_xy = np.array([target_x, target_y], dtype=np.float32)
        delta = target_xy - self.vel_smooth_xy
        for i in range(2):
            if abs(target_xy[i]) < abs(self.vel_smooth_xy[i]):
                max_rate = self.vel_ramp_decel[i] * self.rl_dt
                delta[i] = np.clip(delta[i], -max_rate, max_rate)
        self.vel_smooth_xy = self.vel_smooth_xy + delta
        
        self.twist_cmd.linear.x = float(self.vel_smooth_xy[0])
        self.twist_cmd.linear.y = float(self.vel_smooth_xy[1])
        # ===== 新增结束 =====

        # 没有手柄yaw命令时，运行yaw kp控制（完全不变）
        if abs(ang_vel_z) <= 0.05:
            self.twist_cmd.angular.z = self.speed_raw_cmd.yaw_kp_cal()
        # 有手柄yaw命令时，直接使用手柄命令，并记录当前yaw角作为目标角度（完全不变）
        else:
            self.twist_cmd.angular.z = ang_vel_z
            self.speed_raw_cmd.tar_yaw = self.speed_raw_cmd.now_yaw_multi

        # 取消yaw kp
        # self.twist_cmd.angular.z = float(ang_vel_z)
        # self.speed_raw_cmd.tar_yaw = self.speed_raw_cmd.now_yaw_multi

        # 速度命令限幅（完全不变）
        self.twist_cmd.linear.x = max(
            -self.param["CommandLimit"][0],
            min(self.twist_cmd.linear.x, self.param["CommandLimit"][0])
        )
        self.twist_cmd.linear.y = max(
            -self.param["CommandLimit"][1],
            min(self.twist_cmd.linear.y, self.param["CommandLimit"][1])
        )
        ang_vel_z = max(
            -self.param["CommandLimit"][2],
            min(ang_vel_z, self.param["CommandLimit"][2])
        )

    def twist_callback(self, msg: Twist):
        """接收导航等的速度命令

        Args:
            msg (Twist): 速度命令
        """
        self.speed_raw_cmd.x_vel_cmd = msg.linear.x
        self.speed_raw_cmd.y_vel_cmd = msg.linear.y
        self.speed_raw_cmd.yaw_vel_cmd = msg.angular.z

    def system_state_callback(self, msg: LrsState):
        """接收外部系统状态反馈"""
        self.external_state = {
            'current_state': msg.current_state,
            'current_mode': msg.current_mode,
            'running_status': msg.running_status,
            'motor_health': msg.motor_health
        }
    
    def send_state_command(self, target_state: RunState):
        """发送状态切换命令到外部系统"""
        cmd_msg = LrsCmdState()
        cmd_msg.header.stamp = self.get_clock().now().to_msg()
        
        # 映射内部状态到外部状态
        state_mapping = {
            RunState.IDLE: 0,    # STATE_DISABLED
            RunState.IDLE2: 1,   # STATE_DAMPING
            RunState.STANCE: 2,  # STATE_READY
            RunState.TROT: 3,    # STATE_RUNNING
        }
        
        cmd_msg.cmd_type = 0  # CMD_TYPE_STATE_CHANGE
        cmd_msg.current_state = state_mapping.get(self.run_state, 0)
        cmd_msg.target_state = state_mapping.get(target_state, 0)
        
        # 发布命令
        self.lrs_cmd_pub.publish(cmd_msg)
        self.get_logger().info(
            f"发送状态命令: {self.run_state.name} -> {target_state.name}"
        )

    def show_log(self):
        """输出调试信息到终端"""
        if self.param.get("ShowLog", 0) == 0:
            return

        # 保持一定的频率输出
        self.log_count += 1
        if self.log_count % self.log_decimation != 0:
            return
        
        # 运行时间
        run_time_mean, run_time_max, run_time_min = self.run_time_record.get_time()
        log_runtime = ["runtime[min/mean/max]", f"{run_time_min:.2f}/{run_time_mean:.2f}/{run_time_max:.2f} us"]
        
        # IMU信息
        log_angular_velocity = ["angular_velocity[x/y/z]", 
                               f"{self.propri_obs.base_ang_vel[0]:.2f}/"
                               f"{self.propri_obs.base_ang_vel[1]:.2f}/"
                               f"{self.propri_obs.base_ang_vel[2]:.2f} rad/s"]
        log_gravity = ["gravity[x/y/z]", 
                      f"{self.propri_obs.projected_gravity[0]:.2f}/"
                      f"{self.propri_obs.projected_gravity[1]:.2f}/"
                      f"{self.propri_obs.projected_gravity[2]:.2f}"]
        
        # 手柄命令信息
        log_velocity_commands = ["velocity_commands[x/y/z]", 
                                f"{self.twist_cmd.linear.x:.2f}/"
                                f"{self.twist_cmd.linear.y:.2f}/"
                                f"{self.twist_cmd.angular.z:.2f} m/s"]
        
        # 当前yaw与目标yaw角
        log_now_yaw = ["now_yaw", f"{self.speed_raw_cmd.now_yaw_multi:.2f} rad"]
        log_tar_yaw = ["tar_yaw", f"{self.speed_raw_cmd.tar_yaw:.2f} rad"]
        
        # 运行状态
        log_run_state = ["run_state", f"{self.run_state.name}"]
        
        table_str = tabulate([
            log_runtime, 
            log_gravity, 
            log_angular_velocity, 
            log_velocity_commands, 
            log_now_yaw, 
            log_tar_yaw, 
            log_run_state
        ], tablefmt='simple')

        self.get_logger().info("\n" + table_str)

    def diagnostic_publish(self):
        """发布诊断信息"""
        pass

    @abstractmethod
    def inference(self):
        """
        神经网络推理函数，在该函数中需要完成以下功能：
        1. 构造网络输入变量
        2. 神经网络推理
        3. 命令值发布

        该函数为纯虚函数，需要在子类中定义
        """
        pass

    @abstractmethod
    def zero_cmd(self):
        """
        发送电机零位置命令

        该函数为纯虚函数，需要在子类中定义
        """
        pass
